from gpu4pyscf.scf.uhf import UHF

class KnownValues(unittest.TestCase):
    def test_stability_rhf_unstable(self):
        with StringIO() as output:
            mol = pyscf.M(
                atom = """
                    Fe 0 0.001 0
                    H 1 0 0
                    H -1 0 0.1
                """,
                basis = {"Fe": "def2-svp", "H": "sto-3g"},
                verbose = 0,
            )
            mol.stdout = output
            mol.verbose = 4

            mf = RHF(mol).density_fit(auxbasis = "def2-universal-jkfit")
            mf.conv_tol = 1e-9
            # mf.stdout = output
            test_energy = mf.kernel()

            test_mo_i, test_mo_e, test_stable_i, test_stable_e = mf.stability(external = True, return_status = True, tol = 1e-10)

            log_text = output.getvalue()
            for line in log_text.splitlines():
                if "lowest eigs of" in line:
                    numbers = [float(x) for group in re.findall(r"\[([^\]]+)\]", line) for x in group.split()]
                    numbers = np.array(numbers)
                    if line.startswith("rhf_internal"):
                        test_internal_eigenvalue = numbers
                    elif line.startswith("rhf_real2complex"):
                        test_real2complex_eigenvalue = numbers
                    elif line.startswith("rhf_rhf2uhf"):
                        test_external_eigenvalue = numbers
                    else:
                        raise ValueError("Unknown eigenvalue type: " + line)

        # Reference values obtained from pyscf
